<?php
namespace App\Jobs; use App\Models\{MediaAsset,UploadBatchFile}; use App\Services\Media\MediaVariantProcessor; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\{InteractsWithQueue,SerializesModels}; use Illuminate\Queue\Middleware\WithoutOverlapping; use Throwable;
class ProcessMediaAsset implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=4;public int $timeout=180;public function __construct(public int $assetId,public ?int $batchFileId=null){$this->onQueue('media-high');}public function backoff():array{return [10,30,120];}public function middleware():array{return[(new WithoutOverlapping('media-asset-'.$this->assetId))->expireAfter(240)->dontRelease()];}public function handle(MediaVariantProcessor $processor):void{$asset=MediaAsset::findOrFail($this->assetId);$file=$this->batchFileId?UploadBatchFile::find($this->batchFileId):null;if($file?->batch?->cancelled_at)return;$file?->update(['state'=>'processing','attempts'=>$file->attempts+1]);$asset->update(['state'=>'processing']);try{$processor->process($asset);\App\Jobs\PrepareFaceProcessing::dispatch($asset->id);\App\Jobs\GenerateWatermarkedVariant::dispatch($asset->id);\App\Jobs\ReconcileStorageLedger::dispatch($asset->owner_id);$asset->update(['state'=>'completed']);$file?->update(['state'=>'completed','error'=>null]);$file?->batch->refreshCounts();}catch(Throwable $e){$asset->update(['state'=>'failed']);$file?->update(['state'=>'failed','error'=>'Media processing failed.']);$file?->batch->refreshCounts();throw $e;}}public function failed(?Throwable $e):void{if($file=$this->batchFileId?UploadBatchFile::find($this->batchFileId):null){$file->update(['state'=>'failed','error'=>'Media processing failed after retries.']);$file->batch->refreshCounts();}}}
